function writeStrictJson(filePath, value) {
  const body = JSON.stringify(value, null, 2);
  const fd = fs.openSync(filePath, 'wx', 0o600);
  try {
    fs.writeFileSync(fd, body, { encoding: 'utf8' });
  } finally {
    fs.closeSync(fd);
  }
  return { bytes: Buffer.byteLength(body, 'utf8'), flag: 'wx', mode: 0o600 };
}

