const EventEmitter = require('events');

// Create a SafeEmitter class that extends EventEmitter with these behaviors:
// 1. If an 'error' event is emitted and there are NO error listeners
//    (other than the internal one), it stores the error in this.lastError
//    instead of throwing.
// 2. It tracks the total number of events emitted (all types) in this.eventCount.
// 3. The maxListeners default is set to 5 (not the default 10).
class SafeEmitter extends EventEmitter {

golden_completion:
constructor() {
  super();
  this.lastError = null;
  this.eventCount = 0;
  this.setMaxListeners(5);

  // Internal error handler to prevent throw
  this.on('error', (err) => {
    this.lastError = err;
  });
}

emit(type, ...args) {
  this.eventCount++;
  return super.emit(type, ...args);
}

suffix:
}

