function mergeURLParams(baseURL, overrideURL) {
    const base = new URL(baseURL);
    const override = new URL(overrideURL);

    const baseParams = new URLSearchParams(base.search);
    const overrideParams = new URLSearchParams(override.search);

    for (const [key, value] of overrideParams) {
        baseParams.set(key, value);
    }

    const mergedParams = new URLSearchParams();
    for (const [key, value] of baseParams) {
        if (mergedParams.has(key)) {
            if (!Array.isArray(mergedParams.get(key))) {
                mergedParams.set(key, [mergedParams.get(key)]);
            }
            mergedParams.get(key).push(value);
        } else {
            mergedParams.set(key, value);
        }
    }

    // Sort params alphabetically by key
    const sortedParams = new URLSearchParams();
    for (const key of Array.from(mergedParams.keys()).sort()) {
        const value = mergedParams.getAll(key);
        if (value.length === 1) {
            sortedParams.set(key, value[0]);
        } else {
            value.forEach(v => sortedParams.append(key, v));
        }
    }

    base.search = sortedParams.toString();
    const params = {};
    for (const [key, value] of sortedParams) {
        if (params[key]) {
            if (!Array.isArray(params[key])) {
                params[key] = [params[key]];
            }
            params[key].push(value);
        } else {
            params[key] = value;
        }
    }

    for (const key in params) {
        if (Array.isArray(params[key]) && params[key].length === 1) {
            params[key] = params[key][0];
        }
    }

    return { href: base.href, params };
}

