// Write a function that generates an array of n cryptographically secure
// random integers in the range [min, max) using crypto.randomInt.
// Also compute basic statistics: { values: number[], min: number, max: number, allInRange: boolean }
// NOTE: crypto.randomInt(min, max) returns integers where min is INCLUSIVE
// and max is EXCLUSIVE (like Python's random.randint vs randrange).

golden_completion:
function generateSecureInts(n, min, max) {
    const values = [];
    for (let i = 0; i < n; i++) {
        values.push(crypto.randomInt(min, max));
    }
    const actualMin = Math.min(...values);
    const actualMax = Math.max(...values);
    const allInRange = values.every(v => v >= min && v < max);
    return { values, min: actualMin, max: actualMax, allInRange };
}

