const crypto = require('crypto');
const assert = require('assert');

// Custom HMAC library that derives the signing key before use
// Key derivation: HMAC-SHA256(salt, rawKey) -> derivedKey
// Then: HMAC-SHA256(derivedKey, message) -> signature

function deriveKey(rawKey, salt) {
    return crypto.createHmac('sha256', salt)
        .update(rawKey)
        .digest();
}

function signSha256(message, rawKey, salt) {
    const dk = deriveKey(rawKey, salt);
    return crypto.createHmac('sha256', dk)
        .update(message)
        .digest('hex');
}

// Verify: salt matters
const sig1 = signSha256('hello', 'key', 'salt1');
const sig2 = signSha256('hello', 'key', 'salt2');
assert.notStrictEqual(sig1, sig2);

// Verify: deterministic
assert.strictEqual(
    signSha256('test', 'mykey', 'mysalt'),
    signSha256('test', 'mykey', 'mysalt')
);

