const assert = require('assert');

// Custom Buffer comparison utilities
// Each function returns { result, metadata } with comparison details

function compareBuffersFull(buf1, buf2) {
    const cmp = Buffer.compare(buf1, buf2);
    return {
        result: cmp,
        metadata: {
            buf1Length: buf1.length,
            buf2Length: buf2.length,
            equal: cmp === 0,
            order: cmp < 0 ? 'before' : cmp > 0 ? 'after' : 'equal'
        }
    };
}

const c1 = compareBuffersFull(Buffer.from('abc'), Buffer.from('abd'));
assert.strictEqual(c1.result, -1);
assert.strictEqual(c1.metadata.order, 'before');
assert.strictEqual(c1.metadata.equal, false);

const c2 = compareBuffersFull(Buffer.from('xyz'), Buffer.from('xyz'));
assert.strictEqual(c2.result, 0);
assert.strictEqual(c2.metadata.order, 'equal');

