// We test precise behavior of util.format specifiers
// %s - String
// %d - Number (integer or float parsed via parseFloat)
// %j - JSON (JSON.stringify)
// %o - Object (util.inspect with showHidden and depth)
// %O - Object (util.inspect without showHidden, depth limited)
// %% - literal percent

// Demonstrate %j behavior
assert.strictEqual(format('%j', { a: 1 }), '{"a":1}');
assert.strictEqual(format('%j', [1, 2]), '[1,2]');
assert.strictEqual(format('%j', undefined), 'undefined');  // %j with undefined -> string 'undefined'

// Demonstrate %d behavior: non-numeric strings give NaN
assert.strictEqual(format('%d', '42.5abc'), 'NaN');
assert.strictEqual(format('%d', 'not-a-number'), 'NaN');
assert.strictEqual(format('%d', true), '1');
assert.strictEqual(format('%d', null), '0');
assert.strictEqual(format('%d', false), '0');

// Demonstrate %% (only expanded when format specifiers are present)
assert.strictEqual(format('%s 100%%', 'hi'), 'hi 100%');
assert.strictEqual(format('%%d', 42), '%d 42');  // %% consumes %, d is literal, 42 is extra arg

