const assert = require('assert');

// TextEncoder/TextDecoder behavior tests
// Key behaviors to understand:
// 1. TextDecoder('utf-8', { fatal: true }) throws on invalid sequences
// 2. TextDecoder('utf-8', { ignoreBOM: false }) (default) strips BOM
// 3. TextDecoder('utf-8', { ignoreBOM: true }) preserves BOM

const encoder = new TextEncoder();

// Basic encode/decode round-trip
const encoded = encoder.encode('Hello');
const decoder = new TextDecoder('utf-8');
assert.strictEqual(decoder.decode(encoded), 'Hello');

// BOM handling: default strips BOM
const withBOM = new Uint8Array([0xEF, 0xBB, 0xBF, 0x48, 0x69]); // BOM + "Hi"
const defaultDecoder = new TextDecoder('utf-8');
assert.strictEqual(defaultDecoder.decode(withBOM), 'Hi');  // BOM stripped

// ignoreBOM: true preserves BOM
const bomKeeper = new TextDecoder('utf-8', { ignoreBOM: true });
assert.strictEqual(bomKeeper.decode(withBOM), '﻿Hi');  // BOM preserved

