const assert = require('assert');

// Locale-aware string sorting utilities using Intl.Collator
// Each function returns { sorted, locale, options }

function sortCaseSensitive(arr, locale) {
    const collator = new Intl.Collator(locale, { sensitivity: 'case' });
    const sorted = [...arr].sort(collator.compare);
    return { sorted, locale, options: { sensitivity: 'case' } };
}

// Case-sensitive sort groups by case
const cs1 = sortCaseSensitive(['banana', 'Apple', 'cherry', 'apple'], 'en');
// Intl.Collator with sensitivity:'case' treats accents as equal but case differs
assert.strictEqual(cs1.locale, 'en');

function sortCaseInsensitive(arr, locale) {
    const collator = new Intl.Collator(locale, { sensitivity: 'base' });
    const sorted = [...arr].sort(collator.compare);
    return { sorted, locale, options: { sensitivity: 'base' } };
}

// Base sensitivity: accents and case are ignored
const ci1 = sortCaseInsensitive(['B', 'a', 'C'], 'en');
assert.deepStrictEqual(ci1.sorted, ['a', 'B', 'C']);

