// URL parsing utility using the WHATWG URL API
// Returns structured info about a URL

function parseUrlBasic(urlStr) {
    const url = new URL(urlStr);
    return {
        protocol: url.protocol,     // includes trailing ':'
        hostname: url.hostname,
        port: url.port,             // empty string if default port
        pathname: url.pathname,
        hash: url.hash,             // includes '#' prefix
        origin: url.origin
    };
}

const u1 = parseUrlBasic('https://example.com:8080/path?q=1#section');
assert.strictEqual(u1.protocol, 'https:');
