assert.strictEqual(u1.pathname, '/path');
assert.strictEqual(u1.hash, '#section');
assert.strictEqual(u1.origin, 'https://example.com:8080');

// Default port is empty string
const u2 = parseUrlBasic('https://example.com/');
assert.strictEqual(u2.port, '');
assert.strictEqual(u2.origin, 'https://example.com');

